        elif side == 'left':
            for r in (i, i + 1):
                for c in range(1, w):
                    out[r][c] = 4 if grid[r][c] not in (bg, color) else (color if grid[r][c] == bg else grid[r][c])
        else:
            for r in (i, i + 1):
                for c in range(w - 2, -1, -1):
                    out[r][c] = 4 if grid[r][c] not in (bg, color) else (color if grid[r][c] == bg else grid[r][c])
    return out
